import XCTest

final class UIAutoTests: XCTestCase {

    let app = XCUIApplication(bundleIdentifier: "im.vector.app")

    func dumpHierarchy(_ name: String) {
        let desc = app.debugDescription
        try? desc.write(toFile: "/tmp/hier_\(name).txt", atomically: true, encoding: .utf8)
    }

    func dismissAlertIfNeeded() {
        let alert = app.alerts.firstMatch
        if alert.waitForExistence(timeout: 2) {
            let buttons = alert.buttons.allElementsBoundByIndex
            buttons.last?.tap()
        }
    }

    func testOpenPhoenixMembers() throws {
        app.launch()
        dismissAlertIfNeeded()

        let phoenixRow = app.staticTexts["Project Phoenix"].firstMatch
        XCTAssertTrue(phoenixRow.waitForExistence(timeout: 30), "home screen not loaded")
        dumpHierarchy("home")
        phoenixRow.tap()

        let header = app.staticTexts["Project Phoenix"].firstMatch
        XCTAssertTrue(header.waitForExistence(timeout: 20), "room screen not loaded")
        sleep(2)
        dumpHierarchy("room")
        header.tap()
        sleep(2)
        dumpHierarchy("details")
        dismissAlertIfNeeded()

        let pred = NSPredicate(format: "label CONTAINS[c] 'member' OR label CONTAINS[c] 'people'")
        let membersBtn = app.buttons.matching(pred).firstMatch
        let membersText = app.staticTexts.matching(pred).firstMatch
        if membersBtn.waitForExistence(timeout: 10) {
            membersBtn.tap()
        } else if membersText.waitForExistence(timeout: 5) {
            membersText.tap()
        }
        sleep(2)
        dumpHierarchy("members")
    }
}

import XCTest

final class UIAutoTests: XCTestCase {

    let app = XCUIApplication(bundleIdentifier: "im.vector.app")

    func dumpHierarchy(_ name: String) {
        let desc = app.debugDescription
        try? desc.write(toFile: "/tmp/hier_\(name).txt", atomically: true, encoding: .utf8)
    }

    func dismissSheetIfNeeded() {
        let gotIt = app.buttons["Got it"]
        if gotIt.waitForExistence(timeout: 2) {
            gotIt.tap()
        }
    }

    func testOpenPhoenixMembers() throws {
        app.launch()
        dismissSheetIfNeeded()

        let phoenixRow = app.staticTexts["Project Phoenix"].firstMatch
        XCTAssertTrue(phoenixRow.waitForExistence(timeout: 30), "home screen not loaded")
        phoenixRow.tap()

        let navBar = app.navigationBars["Project Phoenix"]
        XCTAssertTrue(navBar.waitForExistence(timeout: 20), "room screen not loaded")
        sleep(2)
        dismissSheetIfNeeded()

        navBar.coordinate.withOffset(CGVector(dx: 200, dy: 22)).tap()
        sleep(3)
        dismissSheetIfNeeded()
        dumpHierarchy("details2")

        let memberNames = app.staticTexts["Carol"]
        if !memberNames.firstMatch.exists {
            let pred = NSPredicate(format: "label CONTAINS[c] 'member' OR label == 'People' OR label BEGINSWITH 'People'")
            let row = app.staticTexts.matching(pred).firstMatch
            if row.waitForExistence(timeout: 5) {
                row.tap()
                sleep(2)
            }
        }
        dumpHierarchy("members2")
    }
}
